    'Very short alt' => 'Alt molto corto',
    'very short alt text may not describe the image' => 'un testo alternativo molto corto potrebbe non descrivere l\'immagine',
    'via the Plugin Store' => 'tramite il Plugin Store',
    'View accessibility reports' => 'Vedi i rapporti di accessibilità',
